{"path": "book_store.py", "content": "from collections import Counter
from functools import lru_cache

BOOK_PRICE = 800  # cents
DISCOUNTS = {1: 0, 2: 5, 3: 10, 4: 20, 5: 25}


def _group_price(size):
    return size * BOOK_PRICE * (100 - DISCOUNTS[size]) // 100


@lru_cache(maxsize=None)
def _best(counts):
    """Cheapest price (in cents) for a sorted tuple of per-title counts."""
    if not counts:
        return 0
    best = None
    for size in range(1, len(counts) + 1):
        # Taking one copy from each of the `size` most plentiful titles.
        remaining = list(counts)
        for i in range(size):
            remaining[i] -= 1
        rest = tuple(sorted((c for c in remaining if c), reverse=True))
        price = _group_price(size) + _best(rest)
        if best is None or price < best:
            best = price
    return best


def total(basket):
    """Return the lowest price of the basket in cents."""
    counts = tuple(sorted(Counter(basket).values(), reverse=True))
    return _best(counts)
